mapper.update:
UPDATE public.nocode_biz_file_mark
SET deleted = 1, updater = #{actor}, update_time = now()
WHERE user_id = #{userId}
AND entry_id = #{entryId}
AND mark_type = 'FAVORITE'
AND deleted = 0

mapper.select:
SELECT entry_id
FROM public.nocode_biz_file_mark
WHERE user_id = #{userId}
AND object_id = #{objectId}
AND mark_type = #{markType}
AND deleted = 0
ORDER BY COALESCE(access_time, create_time) DESC, id DESC
LIMIT #{limit}
